<script>
	export default {
		data() {
			return {
				id: '',
				type: '',
			
			
				ro:{
					zixunmingcheng : false,
					zixunfenlei : false,
					fengmiantupian : false,
					yuyueshijian : false,
					zixunfeiyong : false,
					xuqiumiaoshu : false,
					yuyuexiangqing : false,
					yonghuzhanghao : false,
					yonghuxingming : false,
					zixunshizhanghao : false,
					zixunshixingming : false,
					ispay : false,
				},
			
				ruleForm: {
					zixunmingcheng: '',
					zixunfenlei: '',
					fengmiantupian: '',
					yuyueshijian: '',
					zixunfeiyong: '',
					xuqiumiaoshu: '',
					yuyuexiangqing: '',
					yonghuzhanghao: '',
					yonghuxingming: '',
					zixunshizhanghao: '',
					zixunshixingming: '',
				},
		

				rules: {
					zixunmingcheng: [
					],
					zixunfenlei: [
					],
					fengmiantupian: [
					],
					yuyueshijian: [
					],
					zixunfeiyong: [
					],
					xuqiumiaoshu: [
					],
					yuyuexiangqing: [
					],
					yonghuzhanghao: [
					],
					yonghuxingming: [
					],
					zixunshizhanghao: [
					],
					zixunshixingming: [
					],
					ispay: [
					],
				},
			};
		},
		props: ["parent"],
		computed: {



		},
		components: {
		},
		created() {
		},
		methods: {
			// 下载
			download(file){
				window.open(`${file}`)
			},
			// 初始化
			init(id,type) {
				if (id) {
					this.id = id;
					this.type = type;
				}
				if(this.type=='info'||this.type=='else'){
					this.info(id);
				}else if(this.type=='logistics'){
					this.logistics=false;
					this.info(id);
				}else if(this.type=='cross'){
					var obj = this.$storage.getObj('crossObj');
					for (var o in obj){
						if(o=='zixunmingcheng'){
							this.ruleForm.zixunmingcheng = obj[o];
							this.ro.zixunmingcheng = true;
							continue;
						}
						if(o=='zixunfenlei'){
							this.ruleForm.zixunfenlei = obj[o];
							this.ro.zixunfenlei = true;
							continue;
						}
						if(o=='fengmiantupian'){
							this.ruleForm.fengmiantupian = obj[o];
							this.ro.fengmiantupian = true;
							continue;
						}
						if(o=='yuyueshijian'){
							this.ruleForm.yuyueshijian = obj[o];
							this.ro.yuyueshijian = true;
							continue;
						}
						if(o=='zixunfeiyong'){
							this.ruleForm.zixunfeiyong = obj[o];
							this.ro.zixunfeiyong = true;
							continue;
						}
						if(o=='xuqiumiaoshu'){
							this.ruleForm.xuqiumiaoshu = obj[o];
							this.ro.xuqiumiaoshu = true;
							continue;
						}
						if(o=='yuyuexiangqing'){
							this.ruleForm.yuyuexiangqing = obj[o];
							this.ro.yuyuexiangqing = true;
							continue;
						}
						if(o=='yonghuzhanghao'){
							this.ruleForm.yonghuzhanghao = obj[o];
							this.ro.yonghuzhanghao = true;
							continue;
						}
						if(o=='yonghuxingming'){
							this.ruleForm.yonghuxingming = obj[o];
							this.ro.yonghuxingming = true;
							continue;
						}
						if(o=='zixunshizhanghao'){
							this.ruleForm.zixunshizhanghao = obj[o];
							this.ro.zixunshizhanghao = true;
							continue;
						}
						if(o=='zixunshixingming'){
							this.ruleForm.zixunshixingming = obj[o];
							this.ro.zixunshixingming = true;
							continue;
						}
					}
				}
				// 获取用户信息
				this.$http({
					url: `${this.$storage.get('sessionTable')}/session`,
					method: "get"
				}).then(({ data }) => {
					if (data && data.code === 0) {
						var json = data.data;
						if(((json.yonghuzhanghao!=''&&json.yonghuzhanghao) || json.yonghuzhanghao==0) && this.$storage.get("role")!="管理员"){
							this.ruleForm.yonghuzhanghao = json.yonghuzhanghao
							this.ro.yonghuzhanghao = true;
						}
						if(((json.yonghuxingming!=''&&json.yonghuxingming) || json.yonghuxingming==0) && this.$storage.get("role")!="管理员"){
							this.ruleForm.yonghuxingming = json.yonghuxingming
							this.ro.yonghuxingming = true;
						}
					} else {
						this.$message.error(data.msg);
					}
				});
			
			},
			// 多级联动参数

			info(id) {
				this.$http({
					url: `yuyuezixun/info/${id}`,
					method: "get"
				}).then(({ data }) => {
					if (data && data.code === 0) {
						this.ruleForm = data.data;
						//解决前台上传图片后台不显示的问题
						let reg=new RegExp('../../../upload','g')//g代表全部
						this.ruleForm.yuyuexiangqing = this.ruleForm.yuyuexiangqing.replace(reg,'../../../springboot907gz3i6/upload');
					} else {
						this.$message.error(data.msg);
					}
				});
			},

			// 提交
			async onSubmit() {
					this.ruleForm.ispay = '未支付'
					if(this.ruleForm.fengmiantupian!=null) {
						this.ruleForm.fengmiantupian = this.ruleForm.fengmiantupian.replace(new RegExp(this.$base.url,"g"),"");
					}
					var objcross = this.$storage.getObj('crossObj');
					await this.$refs["ruleForm"].validate(async valid => {
						if (valid) {
							if(this.type=='cross'){
								var statusColumnName = this.$storage.get('statusColumnName');
								var statusColumnValue = this.$storage.get('statusColumnValue');
								if(statusColumnName!='') {
									var obj = this.$storage.getObj('crossObj');
									if(statusColumnName && !statusColumnName.startsWith("[")) {
										for (var o in obj){
											if(o==statusColumnName){
												obj[o] = statusColumnValue;
											}
										}
										var table = this.$storage.get('crossTable');
										await this.$http({
											url: `${table}/update`,
											method: "post",
											data: obj
										}).then(({ data }) => {});
									}
								}
							}
							
							await this.$http({
								url: `yuyuezixun/${!this.ruleForm.id ? "save" : "update"}`,
								method: "post",
								data: this.ruleForm
							}).then(async ({ data }) => {
								if (data && data.code === 0) {
									this.$message({
										message: "操作成功",
										type: "success",
										duration: 1500,
										onClose: () => {
											if(this.isAuth('yuyuezixun','支付')&&this.type=='cross') {
												this.$confirm('是否跳转支付？').then(_ => {
													this.parent.showFlag = true;
													this.parent.addOrUpdateFlag = false;
													this.parent.yuyuezixunCrossAddOrUpdateFlag = false;
													this.$router.push('/yuyuezixun')
												}).catch(_ => {
													this.parent.showFlag = true;
													this.parent.addOrUpdateFlag = false;
													this.parent.yuyuezixunCrossAddOrUpdateFlag = false;
													this.parent.search();
													this.parent.contentStyleChange();
												});
											}else {
												this.parent.showFlag = true;
												this.parent.addOrUpdateFlag = false;
												this.parent.yuyuezixunCrossAddOrUpdateFlag = false;
												this.parent.search();
												this.parent.contentStyleChange();
											}
											
										}
									});
								} else {
									this.$message.error(data.msg);
								}
							});
						}
					});
			},
			// 获取uuid
			getUUID () {
				return new Date().getTime();
			},
			// 返回
			back() {
				this.parent.showFlag = true;
				this.parent.addOrUpdateFlag = false;
				this.parent.yuyuezixunCrossAddOrUpdateFlag = false;
				this.parent.contentStyleChange();
			},
			fengmiantupianUploadChange(fileUrls) {
				this.ruleForm.fengmiantupian = fileUrls;
			},
		}
	};
</script>
